const j = $input.first().json;
const body = j.body && typeof j.body === 'object' ? j.body : j;
const svg = String(body.svg_base64 || '').trim();
if (!svg) {
  throw new Error('svg_base64 requerido (exportar SVG desde QElectroTech en estación de trabajo; DXF→SVG fuera del contenedor n8n).');
}
return [
  {
    json: {
      payload: {
        kind: 'qelectrotech_svg',
        project_id: body.project_id,
        author: body.author,
        svg_base64: svg,
        source: body.source || 'qelectrotech',
      },
      _echo: {
        project_id: body.project_id,
        author: body.author,
      },
    },
  },
];

const r = $input.first().json;
const echo = $('Build_QET_Payload').first().json._echo || {};
if (r.errors && r.errors.length) {
  throw new Error('Castuo LangGraph: ' + r.errors.join('; '));
}
let plc = '';
let energy = {};
let svgNotes = '';
try {
  const o = JSON.parse(r.analysis);
  if (o.plc_code != null) plc = String(o.plc_code);
  if (o.energy_analysis && typeof o.energy_analysis === 'object') energy = o.energy_analysis;
  if (o.svg_notes != null) svgNotes = String(o.svg_notes);
} catch (e) {
  plc = '';
}
return [
  {
    json: {
      success: true,
      project_id: echo.project_id,
      author: echo.author,
      plc_code: plc,
      energy_analysis: energy,
      svg_notes: svgNotes,
      trace_hash: r.trace_hash || '',
      gaia_http_status: r.gaia_http_status,
      analysis_raw: r.analysis || '',
    },
  },
];
